/**
 * The three links out, as icons with no text: each link is named by its
 * aria-label. The list's layout (direction, --gap, where it shows) belongs
 * to whoever places it: the running margin and the footer.
 */
export default function SocialIcons({ className }: { className?: string }) {
  return (
    <ul className={className ? `${styles.list} ${className}` : styles.list}>
      {LINKS.map(({ label, href, icon }) => (
        <li key={label}>
          <a
            href={href}
            className={styles.link}
            aria-label={label}
            target="_blank"
            rel="noopener"
          >
            {icon}
          </a>
        </li>
      ))}
    </ul>
  );
}
